// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Owned} from "../src/Owned.sol";

contract InvMutTest is Test {
    Owned c;
    function setUp() public { c = new Owned(); }
    function testFuzz_property(address actor, address newOwner) public {
        vm.assume(actor != address(this) && actor != address(c));
        // set owner to a fuzzed owner from the initial owner (address(0))
        vm.prank(address(0));
        c.transferOwnership(newOwner);
        bool ok;
        vm.prank(actor);
        try c.owned() { ok = true; } catch { ok = false; }
        assertTrue(ok == (actor == c.owner()), "owned() must succeed only for the owner");
    }
}
